        max: Optional['types.InspectionMaxAggregateInput'] = None,
        having: Optional['types.InspectionScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.InspectionCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.InspectionScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.InspectionScalarFieldKeys', 'types.SortOrder']]]] = None,
